from pathlib import Path
import shutil
import sys

root = Path(sys.argv[1]) if len(sys.argv) > 1 else Path.cwd()

def replace(path, old, new, count=-1):
    p = root / path
    text = p.read_text()
    if old not in text:
        raise RuntimeError(f"Expected modernization anchor missing in {path}: {old[:80]!r}")
    p.write_text(text.replace(old, new, count))

# Version
replace("gradle.properties", "mod_version=0.5.9-alpha", "mod_version=0.6.0-alpha")

# Shared machine redstone + IO modes.
util = root / "src/main/java/com/loyacrown/enderlegacy/util"
util.mkdir(parents=True, exist_ok=True)
(util / "MachineRedstoneMode.java").write_text('''package com.loyacrown.enderlegacy.util;\n\npublic enum MachineRedstoneMode {\n    ALWAYS_ACTIVE("Always On"),\n    ACTIVE_WITH_SIGNAL("With Signal"),\n    ACTIVE_WITHOUT_SIGNAL("Without Signal"),\n    NEVER_ACTIVE("Never");\n\n    private final String displayName;\n    MachineRedstoneMode(String displayName) { this.displayName = displayName; }\n    public String displayName() { return displayName; }\n    public MachineRedstoneMode next() {\n        MachineRedstoneMode[] values = values();\n        return values[(ordinal() + 1) % values.length];\n    }\n}\n''')
(util / "MachineIOMode.java").write_text('''package com.loyacrown.enderlegacy.util;\n\npublic enum MachineIOMode {\n    DISABLED("Off"), INPUT("Input"), OUTPUT("Output"), INPUT_OUTPUT("In/Out");\n\n    private final String displayName;\n    MachineIOMode(String displayName) { this.displayName = displayName; }\n    public String displayName() { return displayName; }\n    public boolean allowsInput() { return this == INPUT || this == INPUT_OUTPUT; }\n    public boolean allowsOutput() { return this == OUTPUT || this == INPUT_OUTPUT; }\n    public MachineIOMode next() {\n        MachineIOMode[] values = values();\n        return values[(ordinal() + 1) % values.length];\n    }\n}\n''')

