replace(powered, "    public MutableEnergyStorage energy() {\n        return energy;\n    }", '''    public MutableEnergyStorage energy() {\n        return energy;\n    }\n\n    public MachineRedstoneMode getRedstoneMode() { return redstoneMode; }\n\n    public void setRedstoneMode(MachineRedstoneMode mode) {\n        redstoneMode = mode == null ? MachineRedstoneMode.ALWAYS_ACTIVE : mode;\n        setChanged();\n    }\n\n    public void cycleRedstoneMode() { setRedstoneMode(redstoneMode.next()); }\n\n    protected boolean isMachineEnabledByRedstone() {\n        if (level == null) return false;\n        boolean powered = level.hasNeighborSignal(worldPosition);\n        return switch (redstoneMode) {\n            case ALWAYS_ACTIVE -> true;\n            case ACTIVE_WITH_SIGNAL -> powered;\n            case ACTIVE_WITHOUT_SIGNAL -> !powered;\n            case NEVER_ACTIVE -> false;\n        };\n    }''')
