replace(farm, '''    public FarmingStationBlockEntity(BlockPos pos, BlockState state) {\n        super(LegacyBlockEntities.FARMING_STATION.get(), pos, state, 1_000_000, 4_000, 0);\n    }''', '''    public FarmingStationBlockEntity(BlockPos pos, BlockState state) {\n        super(LegacyBlockEntities.FARMING_STATION.get(), pos, state, 1_000_000, 4_000, 0);\n        for (Direction direction : Direction.values()) sideModes.put(direction, MachineIOMode.INPUT_OUTPUT);\n    }''')
