replace(farm, "    public boolean areSupplySlotsLocked() {", '''    public MachineIOMode getSideMode(Direction direction) {\n        return sideModes.getOrDefault(direction, MachineIOMode.INPUT_OUTPUT);\n    }\n\n    public void cycleSideMode(Direction direction) {\n        sideModes.put(direction, getSideMode(direction).next());\n        setChanged();\n    }\n\n    public int getSideModeOrdinal(Direction direction) { return getSideMode(direction).ordinal(); }\n\n    private final class FarmingSidedItemHandler implements IItemHandler {\n        private final Direction side;\n        private FarmingSidedItemHandler(Direction side) { this.side = side; }\n        @Override public int getSlots() { return inventory.getSlots(); }\n        @Override public ItemStack getStackInSlot(int slot) { return inventory.getStackInSlot(slot); }\n        @Override public ItemStack insertItem(int slot, ItemStack stack, boolean simulate) {\n            if (!getSideMode(side).allowsInput() || !isAutomationInputSlot(slot)) return stack;\n            return inventory.insertItem(slot, stack, simulate);\n        }\n        @Override public ItemStack extractItem(int slot, int amount, boolean simulate) {\n            if (!getSideMode(side).allowsOutput() || !isAutomationOutputSlot(slot)) return ItemStack.EMPTY;\n            return inventory.extractItem(slot, amount, simulate);\n        }\n        @Override public int getSlotLimit(int slot) { return inventory.getSlotLimit(slot); }\n        @Override public boolean isItemValid(int slot, ItemStack stack) {\n            return getSideMode(side).allowsInput() && isAutomationInputSlot(slot) && inventory.isItemValid(slot, stack);\n        }\n    }\n\n    private static boolean isAutomationInputSlot(int slot) {\n        return slot == HOE_SLOT || slot == AXE_SLOT || (slot >= FIRST_SUPPLY_SLOT && slot <= LAST_SUPPLY_SLOT) || slot == CAPACITOR_SLOT;\n    }\n    private static boolean isAutomationOutputSlot(int slot) { return slot >= FIRST_OUTPUT_SLOT && slot <= LAST_OUTPUT_SLOT; }\n\n    public boolean areSupplySlotsLocked() {''')
replace(farm, '''                    case 3 -> supplySlotsLocked ? 1 : 0;\n                    default -> 0;''', '''                    case 3 -> supplySlotsLocked ? 1 : 0;\n                    case 4 -> getRedstoneMode().ordinal();\n                    case 5 -> getSideModeOrdinal(Direction.DOWN);\n                    case 6 -> getSideModeOrdinal(Direction.UP);\n                    case 7 -> getSideModeOrdinal(Direction.NORTH);\n                    case 8 -> getSideModeOrdinal(Direction.SOUTH);\n                    case 9 -> getSideModeOrdinal(Direction.WEST);\n                    case 10 -> getSideModeOrdinal(Direction.EAST);\n                    default -> 0;''')
