menu = "src/main/java/com/loyacrown/enderlegacy/menu/FarmingStationMenu.java"
replace(menu, "import net.minecraft.core.BlockPos;", "import net.minecraft.core.BlockPos;\nimport net.minecraft.core.Direction;\nimport com.loyacrown.enderlegacy.util.MachineRedstoneMode;\nimport com.loyacrown.enderlegacy.util.MachineIOMode;")
replace(menu, "public class FarmingStationMenu extends AbstractContainerMenu {", '''public class FarmingStationMenu extends AbstractContainerMenu {\n    public static final int SUPPLY_LOCK_BUTTON_ID = 0;\n    public static final int FIRST_SIDE_BUTTON_ID = 1;\n    public static final int REDSTONE_BUTTON_ID = 7;''')
