replace(screen, "        graphics.blit(TEXTURE, leftPos, topPos, 0, 0, imageWidth, imageHeight);", '''        graphics.blit(TEXTURE, leftPos, topPos, 0, 0, 184, imageHeight);\n        graphics.fill(leftPos + 184, topPos, leftPos + imageWidth, topPos + imageHeight, 0xFFE8E8E8);\n        graphics.fill(leftPos + 185, topPos + 1, leftPos + imageWidth - 1, topPos + imageHeight - 1, 0xFFB8B8B8);''')
