replace(screen, '''        if (supplyLockButton != null) {\n            supplyLockButton.setMessage(Component.translatable(menu.areSupplySlotsLocked()\n                    ? "gui.loyacrowns_ender_legacy.farming_station.unlock"\n                    : "gui.loyacrowns_ender_legacy.farming_station.lock"));\n        }''', '''        if (supplyLockButton != null) {\n            supplyLockButton.setMessage(Component.translatable(menu.areSupplySlotsLocked()\n                    ? "gui.loyacrowns_ender_legacy.farming_station.unlock"\n                    : "gui.loyacrowns_ender_legacy.farming_station.lock"));\n        }\n        for (var entry : sideButtons.entrySet()) entry.getValue().setMessage(Component.literal(sideLabel(entry.getKey())));\n        if (redstoneButton != null) redstoneButton.setMessage(Component.literal(redstoneLabel()));''')

